def fig(*shapes, names=(), lines=(), lo=-6, hi=6):
    """Coordinate plane with polygons and labeled vertices."""
    return plane(lo, hi, polys=[list(s) for s in shapes], pts=[(x, y, n) for x, y, n in names], lines=list(lines))


